import * as THREE from 'three';

const $=s=>document.querySelector(s), world=$('#world');
const scene=new THREE.Scene(); scene.background=new THREE.Color(0x9bc7ce); scene.fog=new THREE.FogExp2(0x9bc7ce,.0068);
const camera=new THREE.PerspectiveCamera(72,innerWidth/innerHeight,.1,450); camera.rotation.order='YXZ';
const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'}); renderer.setPixelRatio(Math.min(devicePixelRatio,1.7)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.12; world.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xc8f4ff,0x35402d,2.1));
const sun=new THREE.DirectionalLight(0xffe6bd,3.1);sun.position.set(-45,75,35);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-100;sun.shadow.camera.right=100;sun.shadow.camera.top=100;sun.shadow.camera.bottom=-100;scene.add(sun);
const fill=new THREE.DirectionalLight(0x58b8e3,.9);fill.position.set(45,28,-50);scene.add(fill);
const mat=(color,rough=.8,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const terrainMat=new THREE.MeshStandardMaterial({vertexColors:true,roughness:.95});
function hash(x,z){let n=Math.sin(x*127.1+z*311.7)*43758.5453;return n-Math.floor(n)}
function heightAt(x,z){const r=Math.hypot(x,z);let hills=Math.sin(x*.075+1.4)*1.25+Math.cos(z*.09-.5)*1.15+Math.sin((x+z)*.045)*2;let ridge=Math.exp(-((x+25)*(x+25)+(z+28)*(z+28))/1700)*9+Math.exp(-((x-39)*(x-39)+(z+5)*(z+5))/1200)*7;let shore=Math.max(0,(r-66)*.42);return Math.max(-1.8, hills+ridge-shore-1.6)}
const N=150, extent=94, positions=[],colors=[],indices=[];
for(let iz=0;iz<=N;iz++)for(let ix=0;ix<=N;ix++){let x=-extent+2*extent*ix/N,z=-extent+2*extent*iz/N,r=Math.hypot(x,z),y=heightAt(x,z);positions.push(x,y,z);let c;if(r>72)c=new THREE.Color(0x777d70);else if(y>4)c=new THREE.Color(0x64745b);else if(y<-.1)c=new THREE.Color(0x75876c);else c=new THREE.Color(0x607a5b);let variation=(hash(ix,iz)-.5)*.11;c.offsetHSL(variation*.14,variation,variation);colors.push(c.r,c.g,c.b);if(ix<N&&iz<N){let a=iz*(N+1)+ix,b=a+1,d=a+N+1,e=d+1;indices.push(a,d,b,b,d,e)}}
const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));geo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));geo.setIndex(indices);geo.computeVertexNormals();const ground=new THREE.Mesh(geo,terrainMat);ground.receiveShadow=true;scene.add(ground);
// distant mountain silhouettes
for(let i=0;i<18;i++){const angle=i/18*Math.PI*2,r=118+hash(i,8)*14,h=18+hash(i,4)*27,rad=12+hash(i,2)*12;const m=new THREE.Mesh(new THREE.ConeGeometry(rad,h,5),mat(i%2?0x718c8a:0x68817f));m.position.set(Math.cos(angle)*r,h/2-2,Math.sin(angle)*r);m.rotation.y=angle+.3;scene.add(m)}
// water ring and sun
const water=new THREE.Mesh(new THREE.CircleGeometry(180,96),new THREE.MeshBasicMaterial({color:0x659eac,transparent:true,opacity:.8}));water.rotation.x=-Math.PI/2;water.position.y=-2.3;scene.add(water);
const sunDisc=new THREE.Mesh(new THREE.SphereGeometry(3,24,16),new THREE.MeshBasicMaterial({color:0xffe4ae}));sunDisc.position.set(-75,51,-130);scene.add(sunDisc);
const woodMat=mat(0x624b32),leafMats=[mat(0x375848),mat(0x45684b),mat(0x557851)],rockMat=mat(0x707a78),grassMat=mat(0x829765);
const worldItems=[],beacons=[],drones=[],decor=[];
function makeTree(x,z,scale=1){let y=heightAt(x,z);const group=new THREE.Group();group.position.set(x,y,z);const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.18*scale,.28*scale,2.7*scale,7),woodMat);trunk.position.y=1.35*scale;trunk.castShadow=true;group.add(trunk);for(let j=0;j<3;j++){const cone=new THREE.Mesh(new THREE.ConeGeometry((1.45-j*.27)*scale,2.2*scale,7),leafMats[Math.floor(hash(x+j,z)*3)]);cone.position.y=(2.5+j*.72)*scale;cone.rotation.y=hash(z,j)*6;cone.castShadow=true;group.add(cone)}scene.add(group);decor.push(group)}
function makeRock(x,z,s=1){let y=heightAt(x,z);const o=new THREE.Mesh(new THREE.DodecahedronGeometry(s,1),rockMat);o.position.set(x,y+s*.42,z);o.scale.set(1.15,.72,.92);o.rotation.set(hash(x,2),hash(z,4)*3,hash(z,9)*.3);o.castShadow=true;o.receiveShadow=true;scene.add(o);decor.push(o)}
for(let i=0;i<76;i++){let a=hash(i,19)*Math.PI*2,r=12+hash(i,21)*57,x=Math.cos(a)*r,z=Math.sin(a)*r;if(Math.hypot(x+5,z+4)<14)continue;makeTree(x,z,.65+hash(i,23)*.75)}
for(let i=0;i<62;i++){let a=hash(i,41)*Math.PI*2,r=7+hash(i,44)*66,x=Math.cos(a)*r,z=Math.sin(a)*r;if(Math.hypot(x+5,z+4)<9)continue;makeRock(x,z,.35+hash(i,48)*1.05)}
// A small abandoned relay camp anchors the starting clearing.
const camp=new THREE.Group();camp.position.set(-5,heightAt(-5,5),5);scene.add(camp);
const floor=new THREE.Mesh(new THREE.CylinderGeometry(4.2,4.2,.15,8),mat(0x585a4c));floor.position.y=.08;floor.receiveShadow=true;camp.add(floor);
for(let i=0;i<3;i++){let post=new THREE.Mesh(new THREE.CylinderGeometry(.1,.14,2.8,6),woodMat);post.position.set(Math.cos(i*2.1)*3,1.4,Math.sin(i*2.1)*3);post.castShadow=true;camp.add(post)}
const tarp=new THREE.Mesh(new THREE.ConeGeometry(3.2,1.5,3),mat(0x526d69));tarp.position.y=2.65;tarp.rotation.y=.5;tarp.castShadow=true;camp.add(tarp);
// collectible aether shards and salvage
const crystalMat=new THREE.MeshStandardMaterial({color:0x65eaff,emissive:0x16aacc,emissiveIntensity:2,roughness:.22,metalness:.18});
function addPickup(x,z,type){const group=new THREE.Group();const y=heightAt(x,z);group.position.set(x,y+.9,z);let shape;if(type==='shard'){shape=new THREE.Mesh(new THREE.OctahedronGeometry(.42,0),crystalMat);shape.scale.set(.72,1.5,.72)}else{shape=new THREE.Mesh(new THREE.IcosahedronGeometry(.42,0),mat(0xb68b53))}shape.castShadow=true;group.add(shape);const halo=new THREE.Mesh(new THREE.TorusGeometry(.55,.025,6,24),new THREE.MeshBasicMaterial({color:type==='shard'?0x67eaff:0xffcf84,transparent:true,opacity:.8}));halo.rotation.x=Math.PI/2;group.add(halo);scene.add(group);worldItems.push({group,shape,halo,type,x,z,taken:false,baseY:y+.9})}
const shardSpots=[[-21,-12],[21,-16],[38,16],[-42,12],[8,37],[-20,44],[48,-35],[-52,-27],[14,-46],[32,47],[-58,36],[55,4]];
shardSpots.forEach(p=>addPickup(...p,'shard'));
[[-12,8],[6,-8],[13,19],[-31,-1],[40,-18],[5,54],[51,26],[-47,-40]].forEach(p=>addPickup(...p,'fiber'));
// Beacon stations: sturdy pylons with a vertical humming core.
function makeBeacon(x,z,id){const g=new THREE.Group();g.position.set(x,heightAt(x,z),z);const base=new THREE.Mesh(new THREE.CylinderGeometry(1.12,1.38,.55,8),mat(0x344c51,.38,.55));base.position.y=.28;base.castShadow=true;base.receiveShadow=true;g.add(base);const stem=new THREE.Mesh(new THREE.CylinderGeometry(.2,.34,2.1,8),mat(0x6f8b8b,.3,.7));stem.position.y=1.5;stem.castShadow=true;g.add(stem);const ring=new THREE.Mesh(new THREE.TorusGeometry(.83,.075,8,32),new THREE.MeshStandardMaterial({color:0x58d9ee,emissive:0x087d99,emissiveIntensity:.3,metalness:.5,roughness:.25}));ring.rotation.x=Math.PI/2;ring.position.y=2.1;g.add(ring);const core=new THREE.Mesh(new THREE.OctahedronGeometry(.43,1),new THREE.MeshStandardMaterial({color:0x65eaff,emissive:0x123f4a,emissiveIntensity:.5,transparent:true,opacity:.88}));core.position.y=2.55;g.add(core);const light=new THREE.PointLight(0x55dfff,.15,12);light.position.y=2.6;g.add(light);scene.add(g);beacons.push({g,x,z,id,active:false,core,ring,light})}
makeBeacon(-38,-31,1);makeBeacon(43,-8,2);makeBeacon(13,49,3);
// Sentinels patrol the valley until they catch your scent.
const droneMat=new THREE.MeshStandardMaterial({color:0x293d43,metalness:.78,roughness:.25});
function makeDrone(x,z,phase){const g=new THREE.Group();g.position.set(x,heightAt(x,z)+3,z);const body=new THREE.Mesh(new THREE.SphereGeometry(.72,16,12),droneMat);body.scale.set(1.25,.65,1);body.castShadow=true;g.add(body);const eye=new THREE.Mesh(new THREE.SphereGeometry(.23,12,8),new THREE.MeshStandardMaterial({color:0xff5969,emissive:0xff1d3e,emissiveIntensity:2.4}));eye.position.set(0,0,.68);g.add(eye);for(let i=0;i<4;i++){let arm=new THREE.Mesh(new THREE.BoxGeometry(1.5,.09,.13),droneMat);arm.position.set(Math.cos(i*Math.PI/2)*.82,0,Math.sin(i*Math.PI/2)*.82);arm.rotation.y=-i*Math.PI/2;g.add(arm);let rotor=new THREE.Mesh(new THREE.TorusGeometry(.36,.035,6,16),mat(0x8ba9a5,.3,.5));rotor.position.set(Math.cos(i*Math.PI/2)*1.47,.12,Math.sin(i*Math.PI/2)*1.47);g.add(rotor)}scene.add(g);drones.push({g,x,z,phase,stun:0})}
makeDrone(20,18,0);makeDrone(-30,18,2);makeDrone(33,-35,4);
// player / controls
const player={x:-5,z:5,y:0,vy:0,yaw:0,pitch:0,health:100,stamina:100,shards:0,fiber:0,active:0,elapsed:0,started:false,dead:false,won:false,grounded:true};
const keys={};let joyVec={x:0,y:0},touchLook=null,lastTime=performance.now(),damageFlash=0,toastTimer=0;
function setToast(text){const e=$('#toast');e.textContent=text;e.classList.add('show');toastTimer=2.2}
function showEnd(win){player.won=win;player.dead=!win;$('#endTag').textContent=win?'SIGNAL RESTORED':'FIELD FAILURE';$('#endTitle').textContent=win?'The valley is yours.':'The wild takes its due.';$('#endText').textContent=win?'All three beacons are online. The signal carries beyond the ridge. You made it.':'Your signal went quiet before the network came alive. The frontier will remember.';$('#end').style.display='flex';document.exitPointerLock?.()}
function startGame(){player.started=true;$('#start').style.display='none';$('#crosshair').style.opacity=innerWidth>700?'1':'0';renderer.domElement.requestPointerLock?.();setToast('SIGNAL LOST — RESTORE ALL 3 BEACONS')}
$('#startBtn').addEventListener('click',startGame);$('#resumeBtn').addEventListener('click',()=>{$('#pause').style.display='none';renderer.domElement.requestPointerLock?.()});$('#restartBtn').addEventListener('click',()=>location.reload());
document.addEventListener('pointerlockchange',()=>{if(!player.started||player.dead||player.won)return;if(document.pointerLockElement!==renderer.domElement&&!('ontouchstart'in window))$('#pause').style.display='flex';else $('#pause').style.display='none'});
document.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Escape'&&player.started&&!player.dead&&!player.won&&!('ontouchstart'in window))$('#pause').style.display=$('#pause').style.display==='flex'?'none':'flex';if(e.code==='KeyE'||e.code==='KeyF')interact();if(e.code==='Space'&&player.grounded)jump()});document.addEventListener('keyup',e=>keys[e.code]=false);
document.addEventListener('mousemove',e=>{if(document.pointerLockElement===renderer.domElement){player.yaw-=e.movementX*.0022;player.pitch=Math.max(-1.25,Math.min(1.25,player.pitch-e.movementY*.0019))}});
renderer.domElement.addEventListener('click',()=>{if(player.started&&!('ontouchstart'in window)&&document.pointerLockElement!==renderer.domElement)renderer.domElement.requestPointerLock?.()});
function jump(){if(player.grounded&&player.stamina>7){player.vy=7.6;player.grounded=false;player.stamina=Math.max(0,player.stamina-7)}}
function interact(){if(!player.started||player.dead||player.won)return;let best=null,dist=4.4;for(const it of worldItems)if(!it.taken){let d=Math.hypot(player.x-it.x,player.z-it.z);if(d<dist){best={kind:'item',item:it,d};dist=d}}for(const b of beacons)if(!b.active){let d=Math.hypot(player.x-b.x,player.z-b.z);if(d<5.4&&d<dist){best={kind:'beacon',item:b,d};dist=d}}if(!best){setToast('NOTHING IN REACH');return}if(best.kind==='item'){const it=best.item;it.taken=true;scene.remove(it.group);if(it.type==='shard'){player.shards++;setToast('AETHER SHARD ACQUIRED  +1')}else{player.fiber++;setToast('SALVAGE FIBER ACQUIRED  +1')}updateHUD()}else{if(player.shards<2){setToast(`BEACON NEEDS 2 SHARDS  •  ${player.shards}/2`);return}player.shards-=2;best.item.active=true;player.active++;best.item.core.material.emissiveIntensity=2.7;best.item.core.material.color.setHex(0xafffff);best.item.ring.material.color.setHex(0x8fffff);best.item.ring.material.emissive=new THREE.Color(0x27dbff);best.item.ring.material.emissiveIntensity=2;best.item.light.intensity=4;best.item.light.distance=25;best.item.g.add(new THREE.PointLight(0x46dfff,1.7,30)).position.y=5;setToast(`BEACON ${best.item.id} ONLINE  •  SIGNAL +${Math.round(player.active/3*100)}%`);updateHUD();if(player.active===3)setTimeout(()=>showEnd(true),1200)}}
// joystick, touch look, and action buttons
