metadata.displayText:
import * as THREE from 'three';

/**
 * AAA Quality Procedural PBR T-Rex Model & Skeleton (Rig) Engine
 * - Detailed Muscle Structure, S-Curved Neck, Jaw Joint, and Tail Counter-Balance Support
 * - PBR Skin Material, Normal Map, and Environmental IBL Reflections
 */
class HighEndTRexEngine {
    constructor(scene) {
        this.scene = scene;
        this.tRexGroup = new THREE.Group();
        this.scene.add(this.tRexGroup);

        this.buildTRexModel();
    }

    buildTRexModel() {
        // High-Quality PBR Skin and Tooth Materials
        const skinMaterial = new THREE.MeshStandardMaterial({
            color: 0x3b4232, // Olive - Carbon Tone
            roughness: 0.65,
            metalness: 0.1,
            bumpScale: 0.04
        });

        const scalePlateMaterial = new THREE.MeshStandardMaterial({
            color: 0x1c1f19,
            roughness: 0.5,
            metalness: 0.2
        });

        const toothMaterial = new THREE.MeshStandardMaterial({
            color: 0xf4efe2,
            roughness: 0.25
        });

        const eyeMaterial = new THREE.MeshStandardMaterial({
            color: 0xffb703,
            emissive: 0xf59e0b,
            emissiveIntensity: 0.7
        });

        // 1. Pelvis and Torso
        const pelvis = new THREE.Group();
        pelvis.position.y = 2.2;
        this.tRexGroup.add(pelvis);

        const torsoGeo = new THREE.CapsuleGeometry(0.65, 1.8, 12, 16);
        torsoGeo.rotateX(Math.PI / 2);
        const torso = new THREE.Mesh(torsoGeo, skinMaterial);
        torso.castShadow = true;
        torso.receiveShadow = true;
        pelvis.add(torso);

        // Dorsal Armor Plates (Osteoderms)
        for (let i = 0; i < 6; i++) {
            const plate = new THREE.Mesh(new THREE.ConeGeometry(0.06, 0.22, 5), scalePlateMaterial);
            plate.position.set(0, 0.75, 0.6 - i * 0.3);
            plate.rotation.x = -0.3;
            torso.add(plate);
        }

        // 2. S-Curved

